import React from "react";
import GlowCursor from "../Designed component/GlowCursor";
export default function ProfessionalExperience() {
  return (
    <section className="bg-neutral-950 px-4 py-24">
      <div className="max-w-6xl mx-auto">
        <div className="relative w-full h-[500px] overflow-hidden rounded-2xl bg-[#050610]">
          <GlowCursor
            color="#67E8F9"
            secondaryColor="#A78BFA"
            trailLength={32}
            trailWidth={8}
            trailTaper={0.8}
            followSpeed={0.16}
            glowIntensity={1.7}
            glowSpread={1.2}
            hotspot={0.65}
            brightness={1.25}
            opacity={1}
            pulseSpeed={1.1}
            noiseStrength={0.03}
            idleFade
            idleTimeout={700}
            fadeDuration={900}
            blendMode="normal"
            className="absolute inset-0"
          />

          {/* Foreground content, layered above the glow canvas */}
          <div className="relative z-10 flex h-full flex-col items-center justify-center text-center px-6">
            <h2 className="text-3xl md:text-5xl font-semibold text-white">
              Professional Experience
            </h2>
            <p className="mt-4 text-neutral-300 max-w-xl">
              A summary of roles, impact, and the tools behind the work.
            </p>
          </div>
        </div>
      </div>
    </section>
  );
}
